-- SEO audit 16 November 2026. Prepared locally; hosted application requires release authorization.
-- Exact audited copy only, scoped to the audited operator. No schedules, prices, inventory or policies changed.
begin;
create or replace function pg_temp.seo_audit_copy(value text) returns text language plpgsql as $$
begin
 value := replace(value, 'Our regular Hop-On Hop-Off service returns in May 2027.', 'Our regular Hop-On Hop-Off service returns in April 2027.');
 value := replace(value, 'Choose the Daily Ticket to hop off, explore and rejoin later departures. Choose the Sightseeing Tour Loop for an approximately two-hour trip, with optional stops of around 10 minutes at the lake, the cathedral and Mesi Bridge.', 'Winter panorama tours last approximately two hours, departing at 09:00, 11:00 and 13:00, with 15-minute photo stops at Shiroka & Lake Shkodra, Cathedral & Historic Center and Mesi Bridge. The panorama-tour ticket covers the selected tour. The hop-on hop-off Daily Ticket is a separate ticket, valid on the selected operating day during operating hours, not for 24 hours. Hop-on hop-off returns in April 2027.');
 value := replace(value, 'the Tour Loop’s short stops do not allow a full visit.', 'the panorama tour’s 15-minute photo stops do not allow a full castle visit.');
 value := replace(value, 'Sightseeing Shkodra provides hop-on hop-off sightseeing transportation services within the city of Shkodra and surrounding attractions.', 'Sightseeing Shkodra provides panorama tours and seasonal hop-on hop-off sightseeing transportation services within the city of Shkodra and surrounding attractions.');
 value := replace(value, 'A ticket is valid for one full day (from first use on the selected date). Passengers may hop on and off at designated stops during the validity period.', 'The panorama-tour ticket covers the selected approximately two-hour tour, with 15-minute photo stops. Winter panorama departures are at 09:00, 11:00 and 13:00. The hop-on hop-off Daily Ticket is a separate ticket, valid only on the selected operating day during that day’s operating hours, not for 24 hours. Daily Ticket passengers may hop on and off at designated stops during those operating hours. Hop-on hop-off returns in April 2027.');
 return value;
end $$;
create or replace function pg_temp.seo_audit_website(doc jsonb) returns jsonb language plpgsql as $$
declare c jsonb; k text;
begin
 if doc is null or jsonb_typeof(doc->'content') is distinct from 'object' then return doc; end if;
 c:=doc->'content';
 foreach k in array array['seasonal.notice','faq.items','legal.terms.text'] loop
  if jsonb_typeof(c->k)='string' then c:=jsonb_set(c,array[k],to_jsonb(pg_temp.seo_audit_copy(c->>k))); end if;
 end loop;
 if c->>'seo.title'='Sightseeing Shkodra' then c:=jsonb_set(c,'{seo.title}',to_jsonb('Shkodra Sightseeing & Panorama Tours | Sightseeing Shkodra'::text));end if;
 if c->>'seo.description' in ('Hop on - hop off sightseeing service in Shkodra.','Discover Shkodra. Tour details and booking information coming soon.') then c:=jsonb_set(c,'{seo.description}',to_jsonb('Explore Shkodra on an approximately two-hour panorama tour with 15-minute photo stops. Winter departures at 09:00, 11:00 and 13:00. View tours and book.'::text));end if;
 return jsonb_set(doc,'{content}',c);
end $$;
update public.content_pages set body=pg_temp.seo_audit_website(body),published_body=pg_temp.seo_audit_website(published_body)
where operator_id='9185510e-0e82-4027-ab1c-8604dad5c92e' and slug='website-homepage'
and (body is distinct from pg_temp.seo_audit_website(body) or published_body is distinct from pg_temp.seo_audit_website(published_body));
